// Code generated by sdk-factory (scripts/generate.sh); DO NOT EDIT.
//
// Request signing. The algorithm parameters come from manifest/sdk.yaml, which
// every LoginRadius SDK renders from, so the Go and Node implementations
// cannot drift — a mismatched expiry format or digest prefix produces a
// signature the API rejects with no useful diagnostic.

import { createHmac } from 'node:crypto';

/** How far ahead the `x-Request-Expires` stamp is set. */
export const SIGNING_EXPIRY_MS = 1200 * 1000;

const DIGEST_HEADER = 'digest';
const EXPIRES_HEADER = 'x-Request-Expires';
const DIGEST_PREFIX = 'SHA-256=';

// Removed from the URL before signing: the tenant secret must never appear in
// the string that is signed, nor on the wire for a signed request.
const STRIP_PARAM = 'apisecret';

/**
 * Whether a request path is in scope for signing.
 *
 * The rule mirrors the reference implementation: management endpoints are
 * signed, except the access-token exchange. Signing anything else produces a
 * digest the API does not expect.
 */
export function shouldSignRequest(path: string): boolean {
  return path.includes('/manage/') && !path.includes('/account/access_token');
}

/**
 * Formats the expiry stamp: UTC, fully zero-padded.
 *
 * Note this is NOT the same shape as the SOTT timestamp, which pads the hour
 * only — the two formats must not share a helper.
 */
function formatExpiry(d: Date): string {
  // toISOString is already UTC and zero-padded; swap the separator and drop
  // the fractional seconds, exactly as the reference implementation does.
  return d.toISOString().replace('T', ' ').replace(/\..+$/, '');
}

/** Result of signing one request. */
export interface SigningHeaders {
  [DIGEST_HEADER]: string;
  [EXPIRES_HEADER]: string;
}

/**
 * Computes the digest and expiry stamp for one request.
 *
 * The signed string is:
 *
 *   expiry + ':' + encodeURIComponent(decodeURIComponent(uri)).toLowerCase()
 *          + optionally ':' + body
 *
 * `uri` must already have the strip parameter removed — see
 * {@link stripSigningParam}.
 *
 * SERVER-SIDE ONLY: signing requires the tenant API secret.
 */
export function signRequest(
  apiSecret: string,
  uri: string,
  body: string | undefined,
  now: Date = new Date(),
): { digest: string; expires: string } {
  const expires = formatExpiry(new Date(now.getTime() + SIGNING_EXPIRY_MS));

  // decode-then-encode normalises whatever escaping the caller used, so the
  // same logical URL always signs identically.
  let decoded: string;
  try {
    decoded = decodeURIComponent(uri);
  } catch {
    // Not decodable means it was never encoded; sign it as-is rather than
    // failing the request.
    decoded = uri;
  }
  const encoded = encodeURIComponent(decoded).toLowerCase();

  const text = body ? `${expires}:${encoded}:${body}` : `${expires}:${encoded}`;
  const mac = createHmac('sha256', apiSecret).update(text).digest('base64');

  return { digest: `${DIGEST_PREFIX}${mac}`, expires };
}

/**
 * Removes the secret query parameter from a URL, returning the result.
 * Returns the input unchanged when the parameter is absent.
 *
 * Accepts absolute or relative URLs; a relative one is resolved against a
 * throwaway base so `URL` can parse it, then rendered back relative.
 */
export function stripSigningParam(uri: string): string {
  const isAbsolute = /^https?:\/\//i.test(uri);
  const base = 'http://placeholder.invalid';
  let parsed: URL;
  try {
    parsed = new URL(uri, base);
  } catch {
    return uri;
  }
  if (!parsed.searchParams.has(STRIP_PARAM)) return uri;
  parsed.searchParams.delete(STRIP_PARAM);
  return isAbsolute ? parsed.toString() : `${parsed.pathname}${parsed.search}${parsed.hash}`;
}

/** Header names this module sets, for callers that need to merge carefully. */
export const SIGNING_HEADERS = { digest: DIGEST_HEADER, expires: EXPIRES_HEADER } as const;
